#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

spec fn sorted_nondecreasing(s: Seq<i8>) -> bool {
    forall|i: int, j: int|
        0 <= i < j < s.len() ==> s[i] <= s[j]
}

fn solve(n_a: i8, n_b: i8, k: i8, m: i8, a: Vec<i8>, b: Vec<i8>) -> (res: &'static str)
    requires
        n_a >= 1,
        n_b >= 1,
        // sizes match lengths (cast to int to avoid overflow issues)
        a@.len() == n_a as int,
        b@.len() == n_b as int,
        // sorted inputs
        sorted_nondecreasing(a@),
        sorted_nondecreasing(b@),
        // 1-based indices in range
        1 <= k <= n_a,
        1 <= m <= n_b,
    ensures
        res == "YES" <==> a@[k as int - 1] < b@[n_b as int - m as int],
        res == "NO"  <==> !(a@[k as int - 1] < b@[n_b as int - m as int]),
{
    let ai: i8 = a[(k - 1) as usize];
    let bj: i8 = b[(n_b - m) as usize];

    if ai < bj {
        "YES"
    } else {
        "NO"
    }
}

} // verus!